async () => {
const tf=document.querySelector('vaadin-text-field'); tf.value=''; tf.dispatchEvent(new CustomEvent('value-changed',{detail:{value:''}}));
await new Promise(r=>setTimeout(r,1500));
const g=document.querySelector('vaadin-grid');
const seen=new Map();
for(let i=0;i<60;i++){
 g.shadowRoot.querySelectorAll('tr').forEach(()=>{});
 const rows=[...g.shadowRoot.querySelectorAll('tbody tr')];
 rows.forEach(r=>{const t=[...r.querySelectorAll('td')].map(c=>c.innerText.trim());if(t.length>4)seen.set(t[2],t)});
 g.scrollToIndex(i*8);
 await new Promise(r=>setTimeout(r,250));
}
return {n:seen.size, lost:[...seen.values()].filter(t=>t[4].startsWith('Laboratory')&&t[3].includes('Closed')).map(t=>t.join('|')), size:g.size, all:[...seen.values()].filter(t=>t[4].startsWith('Laboratory')).length};
}

